mapper.select:
SELECT P.PRODUCT_ID, P.USER_NO, P.PRODUCT_TITLE, P.PRODUCT_STATE, P.PRODUCT_PRICE, P.SUB_CATEGORY_NAME, P.PRODUCT_PLACE, P.TRADE_STATUS, F.FILE_PATH AS MAIN_FILE_PATH FROM PRODUCT P LEFT JOIN PRODUCT_FILE F ON P.PRODUCT_ID = F.PRODUCT_ID AND F.IS_MAIN = 1 WHERE P.USER_NO = #{userNo} AND P.IS_DELETED = 'N'
AND P.TRADE_STATUS = #{tradeStatus}
ORDER BY P.PRODUCT_ID DESC

mapper.insert:

    SELECT product_id_seq.NEXTVAL FROM dual

INSERT INTO product (
    product_id, user_no, product_title, sub_category_name,
    product_place, product_state, product_price, product_explanation, product_keyword
) VALUES (
    #{productId}, #{userNo}, #{title}, #{subCate},
    #{place}, #{state}, #{price}, #{explanation}, #{tag}
)


    SELECT product_file_seq.NEXTVAL FROM dual

INSERT INTO product_file (
    file_id, product_id, original_name, saved_name, file_path, is_main
) VALUES (
    #{fileId}, #{productId}, #{originalName}, #{savedName}, #{filePath}, #{isMain}
)

mapper.delete:
DELETE /*+ NO_PARALLEL(WISHLIST) */ FROM WISHLIST
 WHERE PRODUCT_ID IN (
     SELECT PRODUCT_ID FROM PRODUCT WHERE USER_NO = #{userNo}
 )

mapper.update:
UPDATE PRODUCT
   SET TRADE_STATUS = #{tradeStatus}

   		,BUYER_NO = #{buyerNo}

 WHERE PRODUCT_ID = #{productId}
   AND USER_NO    = #{userNo}
   AND IS_DELETED = 'N'
   AND TRADE_STATUS != 'SOLD'

